    39	const LOYALTY_DISCOUNT_PERCENT = -20;
    40	
    41	/**
    42	 * Every contract after the customer's first is a follow-up contract; the office
    43	 * credits the customer's return against the policy base premium.
    44	 */
    45	const FIRST_CONTRACT_COUNT = 1;
    46	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = -15;
    47	
    48	/**
    49	 * The office's register of policy-wide modifiers. Each entry is an independent
    50	 * ruling: a further modifier is added here, and the rate of an existing one is
    51	 * revised here, without touching how a premium is assembled.
    52	 */
    53	const POLICY_MODIFIERS: readonly PolicyModifier[] = [
    54	  { appliesTo: () => true, ratePercent: INITIAL_ASSESSMENT_SURCHARGE_PERCENT },
    55	  {
    56	    appliesTo: (customer) => customer.yearsWithMHPCO >= LONG_STANDING_FROM_YEARS,
    57	    ratePercent: LOYALTY_DISCOUNT_PERCENT,
    58	  },
    59	  {
    60	    appliesTo: (customer) => customer.previousContracts >= FIRST_CONTRACT_COUNT,
    61	    ratePercent: FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
    62	  },
    63	];
    64	
    65	/**
    66	 * The net policy-wide modifier MHPCO applies to a policy base premium: the
    67	 * surcharges the customer owes less the discounts their standing earns.
    68	 */
    69	export function policyModifiers(customer: Customer, policyBasePremium: number): number {
    70	  return POLICY_MODIFIERS.filter((modifier) => modifier.appliesTo(customer)).reduce(
    71	    (total, modifier) => total + (policyBasePremium * modifier.ratePercent) / PERCENT,
    72	    0,
    73	  );
